// Package lru provides a fixed-capacity cache that evicts the least recently
// used entry. All operations run in O(1) expected time.
package lru

import "fmt"

type entry[K comparable, V any] struct {
	key        K
	value      V
	prev, next *entry[K, V]
}

// Cache is a least-recently-used cache. The zero value is not usable; create
// one with New. A Cache is not safe for concurrent use.
type Cache[K comparable, V any] struct {
	capacity int
	items    map[K]*entry[K, V]
	// root is a sentinel of a circular doubly linked list: root.next is the
	// most recently used entry and root.prev the least recently used.
	root entry[K, V]
}

// New returns an empty cache holding at most capacity entries.
// It panics if capacity is less than 1.
func New[K comparable, V any](capacity int) *Cache[K, V] {
	if capacity < 1 {
		panic(fmt.Sprintf("lru: capacity must be positive: %d", capacity))
	}
	c := &Cache[K, V]{
		capacity: capacity,
		items:    make(map[K]*entry[K, V], min(capacity, 1<<16)),
	}
	c.root.next = &c.root
	c.root.prev = &c.root
	return c
}

// Set inserts or overwrites the value for key and marks key as most recently
// used. If the cache then exceeds its capacity, the least recently used entry
// is evicted.
func (c *Cache[K, V]) Set(key K, value V) {
	if e, ok := c.items[key]; ok {
		e.value = value
		c.moveToFront(e)
		return
	}
	var e *entry[K, V]
	if len(c.items) >= c.capacity {
		// Recycle the evicted entry instead of allocating a new one.
		e = c.root.prev
		c.unlink(e)
		delete(c.items, e.key)
	} else {
		e = new(entry[K, V])
	}
	e.key, e.value = key, value
	c.pushFront(e)
	c.items[key] = e
}

// Get returns the value for key and whether it was present. A hit marks key as
// most recently used.
func (c *Cache[K, V]) Get(key K) (V, bool) {
	e, ok := c.items[key]
	if !ok {
		var zero V
		return zero, false
	}
	c.moveToFront(e)
	return e.value, true
}

// Delete removes key and reports whether it was present.
func (c *Cache[K, V]) Delete(key K) bool {
	e, ok := c.items[key]
	if !ok {
		return false
	}
	c.unlink(e)
	delete(c.items, key)
	return true
}

// Len returns the number of entries held.
func (c *Cache[K, V]) Len() int {
	return len(c.items)
}

func (c *Cache[K, V]) unlink(e *entry[K, V]) {
	e.prev.next = e.next
	e.next.prev = e.prev
	e.prev, e.next = nil, nil
}

func (c *Cache[K, V]) pushFront(e *entry[K, V]) {
	e.prev = &c.root
	e.next = c.root.next
	c.root.next.prev = e
	c.root.next = e
}

func (c *Cache[K, V]) moveToFront(e *entry[K, V]) {
	if c.root.next == e {
		return
	}
	c.unlink(e)
	c.pushFront(e)
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if c.Len() != 2 {
		t.Fatalf("Len() = %d; want 2", c.Len())
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New[string, string](2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q; want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDelete(t *testing.T) {
	c := New[string, int](1)
	c.Set("x", 1)
	if !c.Delete("x") {
		t.Fatal("first Delete should report presence")
	}
	if c.Delete("x") {
		t.Fatal("second Delete should report absence")
	}
	if c.Len() != 0 {
		t.Fatalf("Len() = %d; want 0", c.Len())
	}
	c.Set("y", 2)
	c.Set("z", 3)
	if _, ok := c.Get("y"); ok {
		t.Fatal("y should have been evicted")
	}
}

// Command app simulates an LRU cache driven by commands read from standard
// input, as described in SPEC.md.
package main

import (
	"bufio"
	"bytes"
	"errors"
	"fmt"
	"io"
	"os"
	"strconv"

	"lrusim/lru"
)

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "lru:", err)
		os.Exit(1)
	}
}

func run(r io.Reader, w io.Writer) error {
	input, err := io.ReadAll(r)
	if err != nil {
		return err
	}
	out := bufio.NewWriterSize(w, 1<<16)

	lines := lineScanner{data: input}
	first, ok := lines.next()
	for ok && len(bytes.TrimSpace(first)) == 0 {
		first, ok = lines.next()
	}
	if !ok {
		return nil
	}
	capacity, err := strconv.Atoi(string(bytes.TrimSpace(first)))
	if err != nil {
		return fmt.Errorf("invalid capacity: %w", err)
	}
	if capacity < 1 {
		return errors.New("capacity must be positive")
	}

	cache := lru.New[string, string](capacity)
	for line, ok := lines.next(); ok; line, ok = lines.next() {
		execute(cache, line, out)
	}
	return out.Flush()
}

// execute applies one command line to the cache. Malformed, blank, or
// unrecognised lines produce no output.
func execute(cache *lru.Cache[string, string], line []byte, out *bufio.Writer) {
	cmd, rest, hasArg := bytes.Cut(line, []byte{' '})
	switch string(cmd) {
	case "SET":
		key, value, ok := bytes.Cut(rest, []byte{' '})
		if !hasArg || !ok {
			return
		}
		cache.Set(string(key), string(value))
	case "GET":
		if !hasArg {
			return
		}
		if v, ok := cache.Get(string(rest)); ok {
			out.WriteString(v)
		} else {
			out.WriteString("NULL")
		}
		out.WriteByte('\n')
	case "DEL":
		if !hasArg {
			return
		}
		if cache.Delete(string(rest)) {
			out.WriteString("1\n")
		} else {
			out.WriteString("0\n")
		}
	case "SIZE":
		out.Write(strconv.AppendInt(out.AvailableBuffer(), int64(cache.Len()), 10))
		out.WriteByte('\n')
	}
}

// lineScanner splits a buffer into lines, tolerating a trailing '\r' and a
// missing final newline.
type lineScanner struct {
	data []byte
	pos  int
}

func (s *lineScanner) next() ([]byte, bool) {
	if s.pos >= len(s.data) {
		return nil, false
	}
	rest := s.data[s.pos:]
	line := rest
	if i := bytes.IndexByte(rest, '\n'); i >= 0 {
		line = rest[:i]
		s.pos += i + 1
	} else {
		s.pos = len(s.data)
	}
	line = bytes.TrimSuffix(line, []byte{'\r'})
	return line, true
}
